'use strict';

const originalApiV2 = api;
api = async function(path, data) {
  try { return await originalApiV2(path, data); }
  catch(error) { if(error.message.includes('请先登录')) $('login-screen').hidden=false; throw error; }
};

$('login-form').onsubmit=safe(async event=>{
  event.preventDefault();
  $('login-error').textContent='';
  try {
    await api('/api/login',{username:$('login-user').value,password:$('login-password').value});
    $('login-password').value='';
    await bootstrap();
    toast('已进入独立体验空间');
  } catch(error) { $('login-password').value=''; $('login-error').textContent=error.message; }
});

async function updateWorkspaceStatus(status) {
  let account=$('account-controls');
  if(!account){account=document.createElement('div');account.id='account-controls';document.querySelector('.header-right').append(account);}
  account.replaceChildren();
  if(status.auth_enabled){
    const label=document.createElement('span');label.className='tiny';label.textContent='独立评审空间';account.append(label);
    const logout=document.createElement('button');logout.className='text-link';logout.textContent='退出';
    logout.onclick=safe(async()=>{await api('/api/logout',{});location.reload();});account.append(logout);
  }
  await loadMetricsV2();
}

const metadataFieldsV2=[['source_name','数据来源名称'],['source_url','来源网址或书目信息'],['authorization','授权或使用依据'],['subject','学科'],['grade','适用年级'],['edition','版本与日期']];
const originalShowDocumentV2=showDocument;
showDocument=async function(id){
  await originalShowDocumentV2(id);
  const doc=await api('/api/documents/'+id);
  const form=document.createElement('form');form.className='metadata-editor';
  form.innerHTML='<h3>教材来源与审核信息</h3><p class="tiny">请填写可核对的来源和授权依据。审核标记由使用者确认，不等于系统验证版权。</p>'+metadataFieldsV2.map(([k,label])=>`<label for="meta-${k}">${esc(label)}</label><input id="meta-${k}" maxlength="500" value="${esc((doc.metadata||{})[k]||'')}">`).join('')+
    `<label for="meta-review">教材审核</label><select id="meta-review"><option value="pending">待教师审核</option><option value="reviewed">已由教师审核</option></select><button class="btn soft" type="submit">保存来源信息</button>`;
  $('document-detail').prepend(form);
  $('meta-review').value=(doc.metadata||{}).review_status||'pending';
  form.onsubmit=safe(async event=>{event.preventDefault();const metadata={};metadataFieldsV2.forEach(([k])=>metadata[k]=$('meta-'+k).value);metadata.review_status=$('meta-review').value;await api('/api/metadata',{doc_id:id,metadata});await loadDocs(id);toast('来源信息已保存');});
};

const originalShowResultV2=showResult;
showResult=function(run){
  originalShowResultV2(run);
  document.getElementById('explain-pagination')?.remove();
  const progress=run.explain_progress;
  if(progress){
    const section=document.createElement('section');section.id='explain-pagination';
    const text=document.createElement('p');text.className='tiny';
    text.textContent=`${progress.scope}：本次第 ${progress.count?progress.offset+1:0}—${progress.next_offset} 句，共 ${progress.total} 句。${progress.has_more?'还有内容未处理。':'已到该范围末尾。'}${run.translation_source_valid===false?'模型未按指定原句返回，已退回原文卡，本批需要重试或人工填写。':''}`;
    section.append(text);
    if(progress.has_more||run.translation_source_valid===false){
      const next=document.createElement('button');next.className='btn soft';
      next.textContent=run.translation_source_valid===false?'重试本批讲解':'继续讲解下一组';
      next.onclick=safe(async()=>{next.disabled=true;try{await executeTask({doc_id:run.doc_id,goal:run.goal,intent:'explain',mode:run.mode,
        knowledge_point:progress.knowledge_point||'',explain_offset:run.translation_source_valid===false?progress.offset:progress.next_offset,expected_revision:progress.doc_revision});}finally{next.disabled=false;}});
      section.append(next);
    }
    $('answer').before(section);
  }
  $('bilingual-cards').innerHTML='';
  if(run.bilingual?.length){
    $('bilingual-cards').innerHTML='<h3>逐句藏汉对照与教师复核</h3><p class="tiny">空白表示尚未翻译。模型译文在教师确认前不能作为标准译文；原句只核对是否来自教材，不自动判断译文正确性。</p>'+run.bilingual.map((c,i)=>`<article class="sentence-card"><p class="tiny">${esc(c.source_id)} · ${c.reviewed?'已人工确认':'待教师复核'}</p><p class="original-sentence">${esc(c.original)}</p><label for="bo-${i}">藏文</label><textarea id="bo-${i}" rows="2">${esc(c.translation_bo)}</textarea><label for="zh-${i}">汉文</label><textarea id="zh-${i}" rows="2">${esc(c.translation_zh)}</textarea><label for="explain-${i}">讲解与备注</label><textarea id="explain-${i}" rows="2">${esc(c.explanation)}</textarea><button class="btn soft" data-card="${i}">保存并确认这一句</button></article>`).join('');
    $('bilingual-cards').querySelectorAll('[data-card]').forEach(button=>button.onclick=safe(async()=>{
      const i=Number(button.dataset.card);
      const updated=await api('/api/bilingual/review',{run_id:run.id,index:i,translation_bo:$('bo-'+i).value,translation_zh:$('zh-'+i).value,explanation:$('explain-'+i).value});
      showResult(updated);toast('教师确认已保存');
    }));
  }
  $('lesson-revision').hidden=run.intent!=='lesson';
  $('revision-info').textContent=`当前第 ${run.revision||1} 版 · 修改会另存，不覆盖上一版。`;
  safe(loadMetricsV2)();
};
$('revise-lesson').onclick=safe(async()=>{
  if(!latestRun||latestRun.intent!=='lesson') throw Error('请先生成或加载教案');
  const goal=$('revision-goal').value.trim();if(!goal)throw Error('请输入修改要求');
  const parent=latestRun;
  await executeTask({doc_id:parent.doc_id,parent_run_id:parent.id,intent:'lesson',mode:$('run-mode').value,goal});
  $('revision-goal').value='';
});

const attemptsPanelV2=document.createElement('article');attemptsPanelV2.className='panel attempts-panel';
attemptsPanelV2.innerHTML='<div class="panel-title"><h2>作答记录与错题重练</h2><button class="text-link" id="refresh-attempts">刷新记录</button></div><p class="tiny">每次提交单独保存。这里展示历史错误；之后答对不会删除此前记录。</p><div id="attempts-list"></div>';
$('view-practice').append(attemptsPanelV2);
async function loadAttemptsV2(){
  const attempts=await api('/api/attempts');
  $('attempts-list').innerHTML=attempts.length?attempts.map(a=>{
    const wrong=a.items.filter(i=>!i.correct);
    return `<details class="attempt-record" data-attempt="${esc(a.id)}"><summary>${a.demo_submission?'程序示范作答（非学生成绩） · ':''}${new Date(a.created||Date.now()).toLocaleString('zh-CN')} · ${a.score} 分 · ${wrong.length} 道错题</summary>${wrong.map(q=>`<div class="grade-item wrong"><p>${esc(q.prompt)}</p><p>你的答案：${esc(q.given||'未作答')}<br>评分答案：${esc(q.expected)}</p><p>${esc(q.feedback)}</p><details><summary>原文依据 [${esc(q.source_id)}]</summary><p>${esc(q.source_quote)}</p></details></div>`).join('')}${wrong.length?`<button class="btn soft" data-retry="${esc(a.id)}">只练这次的错题</button>`:'<p class="muted">本次没有错题。</p>'}</details>`;
  }).join(''):'<p class="muted">提交练习后，这里会保存作答与错题记录。</p>';
  $('attempts-list').querySelectorAll('[data-retry]').forEach(button=>button.onclick=safe(async()=>{const quiz=await api('/api/retry',{attempt_id:button.dataset.retry});showQuiz(quiz);$('quiz-form').scrollIntoView({behavior:'smooth',block:'start'});toast('已加载错题重练');}));
}
$('refresh-attempts').onclick=safe(loadAttemptsV2);
const originalViewV2=view;
view=function(name){originalViewV2(name);if(name==='practice')safe(loadAttemptsV2)();if(name==='settings')safe(loadMetricsV2)();};
const originalQuizSubmitV2=$('quiz-form').onsubmit;
$('quiz-form').onsubmit=async event=>{await originalQuizSubmitV2(event);await safe(loadAttemptsV2)();await safe(loadMetricsV2)();};

const connectionPanelV2=document.createElement('article');connectionPanelV2.className='panel connection-panel';
connectionPanelV2.innerHTML='<h2>实际连接检测</h2><p class="muted">检测模型会向你配置的服务发送一次短文本请求，可能消耗少量额度，不发送教材。OCR 检测只访问可选健康地址，不上传演示图片。</p><div class="probe-buttons"><button class="btn soft" data-probe="llm">检测大模型连接</button><button class="btn soft" data-probe="ocr">检测 OCR 服务</button></div><div id="probe-results" aria-live="polite"></div>';
$('view-settings').append(connectionPanelV2);
document.querySelectorAll('[data-probe]').forEach(button=>button.onclick=safe(async()=>{button.disabled=true;try{const result=await api('/api/connections/test',{service:button.dataset.probe});const states={unconfigured:'未配置',available:'连接通过',unavailable:'检测失败',unverified:'尚未验证'};const p=document.createElement('p');p.className='probe-result';p.textContent=`${result.service==='llm'?'大模型':'OCR'}：${states[result.state]}。${result.message}`;$('probe-results').prepend(p);}finally{button.disabled=false;}}));

const metricsPanelV2=document.createElement('article');metricsPanelV2.className='panel metrics-panel';
metricsPanelV2.innerHTML='<div class="panel-title"><h2>本空间运行统计</h2><button class="text-link" id="refresh-metrics">刷新</button></div><div id="metrics-content"></div><p class="tiny">这里只统计程序运行与练习结果，不能替代真实教师试用、翻译质量或学习收益评测。</p>';
$('view-settings').append(metricsPanelV2);
async function loadMetricsV2(){
  const m=await api('/api/metrics');
  $('metrics-content').innerHTML=`<div class="metrics-grid"><div>任务记录<span>${m.runs}</span><small>${esc(m.run_window)}</small></div><div>作答记录<span>${m.attempts}</span><small>${esc(m.attempt_window)}</small></div><div>平均练习分<span>${m.mean_score==null?'暂无':m.mean_score}</span><small>原文练习评分</small></div><div>平均任务耗时<span>${m.mean_duration_ms==null?'暂无':(m.mean_duration_ms/1000).toFixed(2)+'s'}</span><small>含模型请求耗时</small></div></div>`;
}
$('refresh-metrics').onclick=safe(loadMetricsV2);
safe(bootstrap)();

// Public demonstration credentials shown at the owner's explicit request.
document.querySelectorAll('[data-login-copy]').forEach(button=>button.onclick=safe(async()=>{
  const isUser=button.dataset.loginCopy==='user';
  const value=$(isUser?'demo-login-user':'demo-login-password').textContent;
  $(isUser?'login-user':'login-password').value=value;
  try{await navigator.clipboard.writeText(value);toast(isUser?'账号已复制':'密码已复制');}
  catch(error){toast('已填入输入框，也可长按上方文字复制');}
}));

