const trainingPanel=document.createElement('article');trainingPanel.className='panel training-panel';trainingPanel.id='training-panel';
$('view-settings').querySelector('.page-heading').after(trainingPanel);
const trainingLink=document.createElement('button');trainingLink.className='btn soft';trainingLink.textContent='查看OCR训练记录';
trainingLink.onclick=()=>{view('settings');trainingPanel.scrollIntoView({behavior:'smooth',block:'start'});};
$('view-logs').querySelector('.page-heading').append(trainingLink);
function exportTrainingRecord(record,kind){
  const formats={report:['微调实验报告.md','text/markdown;charset=utf-8',record.exports.report],
    training_log:['训练原始日志.txt','text/plain;charset=utf-8',record.exports.training_log],
    split_csv:['100页数据划分.csv','text/csv;charset=utf-8','\ufeff'+record.exports.split_csv],
    record:['训练记录与评测证据.json','application/json;charset=utf-8',JSON.stringify(record,null,2)]};
  const [filename,type,text]=formats[kind];const url=URL.createObjectURL(new Blob([text],{type}));
  const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
}
function renderTrainingRecords(){
  const labels={base_float:'原始浮点模型 · 原生引擎',pilot_50:'50步微调 · 原生引擎',round1_600:'600步微调 · 原生引擎',agent_current:'线上原模型 · Tesseract.js'};
  trainingPanel.innerHTML='<h2>OCR模型训练与评测记录</h2><p class="muted">这里记录已完成的本机CPU微调实验。实验记录独立保存，并提供原始日志和评测证据下载。</p>'+
    verifiedTrainingRecords.map((record,index)=>{
      const minutes=Math.floor(record.training_seconds/60),seconds=Math.round(record.training_seconds%60),deployed=record.deployment_status==='deployed_experimental';
      const val=Object.fromEntries(record.validation.map(r=>[r.model,r])),test=Object.fromEntries(record.test.map(r=>[r.model,r]));
      const percent=row=>row?(row.weighted_cer*100).toFixed(3)+'%':'未入选最终测试';
      return `<section class="training-record"><h3>${esc(record.title)}</h3><p class="training-state">训练已完成 · ${deployed?'微调量化模型已接入线上':'实验模型待接入'} · 标注待人工复核</p><p>${deployed?'当前默认本地OCR：':'线上识别仍使用'}${esc(record.active_model)}。${deployed?'原模型已保留，可在上传区切换；待教师复核。':'本次训练没有自动切换线上OCR。'}</p><div class="metrics-grid"><div>训练／验证／测试页数<span>${record.split.train}／${record.split.validation}／${record.split.test}</span><small>先整页分组，再切行</small></div><div>CPU微调<span>${record.iterations}步</span><small>未使用GPU</small></div><div>纯训练耗时<span>${minutes}分${seconds}秒</span><small>训练文件 ${record.samples.train} 条，验证文件 ${record.samples.validation} 条</small></div><div>训练进程峰值内存<span>${record.peak_process_mib.toFixed(1)} MiB</span><small>不代表整台电脑总占用</small></div></div>${deployed?`<h3>网页识别引擎部署回归</h3><p>微调量化模型验证集差异率 ${(record.deployment.regression.validation.weighted_cer*100).toFixed(3)}%，原测试页回归差异率 ${(record.deployment.regression.test.weighted_cer*100).toFixed(3)}%。</p><p class="tiny">量化权重SHA256：<code class="training-hash">${esc(record.deployment.model_sha256)}</code><br>${esc(record.deployment.note)}</p>`:''}<h3>验证集与独立测试结果</h3><p class="tiny">数值越低，文字与所附TXT的差异越少；不等于教学效果或翻译准确率。不同引擎之间的差异不能全部归因于微调。</p><div class="training-table-scroll"><table class="training-table"><thead><tr><th>模型与引擎</th><th>验证集10页</th><th>独立测试10页</th></tr></thead><tbody>${Object.keys(labels).map(name=>`<tr><td>${labels[name]}</td><td>${percent(val[name])}</td><td>${percent(test[name])}</td></tr>`).join('')}</tbody></table></div><p class="tiny">${esc(record.metric)} ${esc(record.selected_by)}</p><details open><summary>查看训练过程记录</summary><ol class="training-timeline">${record.timeline.map(event=>`<li><p>${esc(event.title)}</p><small>${new Date(event.at).toLocaleString('zh-CN')}</small><p class="tiny">${esc(event.detail)}</p></li>`).join('')}</ol></details><details><summary>数据划分与防泄漏检查</summary><p>随机种子：${record.seed}。第24页和第50页相似，归为同一组；已演示的${record.prior_seen_pages.join('、')}页固定进入训练集。</p><p class="tiny">下载100页划分表可查看每页所属集合、重复组与图片SHA256。</p></details><details><summary>查看独立测试逐页对照</summary><div class="training-table-scroll"><table class="training-table"><thead><tr><th>原始页</th><th>原始浮点模型</th><th>600步微调</th><th>线上原模型</th></tr></thead><tbody>${record.test_pages.filter(r=>r.model==='base_float').sort((a,b)=>a.page_id-b.page_id).map(row=>{const byName=Object.fromEntries(record.test_pages.filter(r=>r.page_id===row.page_id).map(r=>[r.model,r]));return `<tr><td>${row.page_id}</td><td>${(row.cer*100).toFixed(3)}%</td><td>${(byName.round1_600.cer*100).toFixed(3)}%</td><td>${(byName.agent_current.cer*100).toFixed(3)}%</td></tr>`;}).join('')}</tbody></table></div></details><details><summary>实验边界与待完成事项</summary><ul>${record.limitations.map(text=>`<li>${esc(text)}</li>`).join('')}</ul></details><div class="probe-buttons training-downloads"><button class="btn soft" data-training-export="report" data-training-index="${index}">下载实验报告</button><button class="btn soft" data-training-export="training_log" data-training-index="${index}">下载原始训练日志</button><button class="btn soft" data-training-export="split_csv" data-training-index="${index}">下载100页划分表</button><button class="btn soft" data-training-export="record" data-training-index="${index}">导出完整记录JSON</button></div><p class="tiny">记录编号：${esc(record.id)}<br>记录导入时间：${new Date(record.imported_at).toLocaleString('zh-CN')}<br>实验权重SHA256：<code class="training-hash">${esc(record.model_sha256)}</code></p></section>`;
    }).join('');
  trainingPanel.querySelectorAll('[data-training-export]').forEach(button=>button.onclick=()=>exportTrainingRecord(verifiedTrainingRecords[Number(button.dataset.trainingIndex)],button.dataset.trainingExport));
}
renderTrainingRecords();
